import * as React from 'react';
import * as S from '@primasoftllc/design-system';
import '@primasoftllc/design-system/styles.css';

function App() {
    var example = React.useState(null), size = React.useState('md'), archived = React.useState(false), saved = React.useState(false), notifications = React.useState('checked');
    function close() { example[1](null); }
    var mode = example[0];
    return <div className="dsdialog-example">
    <style>{exampleStyles}</style>
    <div className={"demo-stack"}>
    <div className={"demo-stack"}>
    <p>
    {'Последствие объяснено до подтверждения. Отмена стоит перед главным действием.'}
    </p>
    <div className={'row'}>
    <S.DsButton tone={'danger'} icon={'archive'} onClick={function () { example[1]('archive'); }}>
    {'Переместить в архив…'}
    </S.DsButton>
    </div>
    <p className={'cap'} role={'status'}>
    {archived[0] ? 'Объект перемещён в архив.' : 'Объект доступен на карте.'}
    </p>
    </div>
    {mode === "archive" ? mode ? <div className={'stage'}>
    <S.DsDialog open={true} size={mode === 'archive' ? 'sm' : mode === 'history' ? size[0] : 'md'} tone={mode === 'archive' ? 'danger' : undefined} title={mode === 'archive' ? 'Переместить объект «Volvo FH16» в архив?' : mode === 'settings' ? 'Уведомления об объекте' : 'История объекта'} description={mode === 'archive' ? 'Объект пропадёт с карты. Его история останется доступна в отчётах.' : mode === 'settings' ? 'Выберите, какие события получать.' : undefined} onClose={close} actions={mode === 'history' ? [<S.DsButton key={'close'} tone={'secondary'} onClick={close}>
        {'Закрыть'}
        </S.DsButton>] : [
                <S.DsButton key={'cancel'} tone={'secondary'} onClick={close}>
        {'Отмена'}
        </S.DsButton>,
                <S.DsButton key={'confirm'} tone={mode === 'archive' ? 'danger' : 'primary'} onClick={function () {
                        if (mode === 'archive')
                            archived[1](true);
                        else
                            saved[1](true);
                        close();
                    }}>
        {mode === 'archive' ? 'Переместить в архив' : 'Сохранить'}
        </S.DsButton>
            ]}>
    {mode === 'settings' ? <div className={'options'}>
    <S.DsCheckbox label={'Изменение статуса'} state={notifications[0]} onChange={notifications[1]}/>
    </div> : mode === 'history' ? Array.from({ length: 24 }, function (_, i) {
                return <p className={'entry'} key={i}>
    {'Событие ' + (i + 1) + ' · Обновлена информация об объекте.'}
    </p>;
            }) : null}
    </S.DsDialog>
    </div> : null : null}
    </div>
    </div>;
}

const exampleStyles = ".dsdialog-example{font:var(--ds-type-body);color:var(--ds-fg)}\n.dsdialog-example .demo-stack{display:flex;flex-direction:column;gap:16px;min-width:0}\n.dsdialog-example p{margin:0}\n.dsdialog-example .row{display:flex;flex-wrap:wrap;gap:8px;align-items:center}\n.dsdialog-example .cap{font:var(--ds-type-caption);color:var(--ds-fg-muted)}\n.dsdialog-example .stage{position:relative;transform:translateZ(0);min-height:620px}\n.dsdialog-example .options{display:flex;flex-direction:column;gap:16px}\n.dsdialog-example .entry{padding:12px 0;border-bottom:1px solid var(--ds-border)}";

export { App as Example };

